func _js_trigger_gc(tls *libc.TLS, rt uintptr, size Tsize_t) {
	var force_gc TBOOL
	_ = force_gc
	force_gc = libc.BoolInt32((*TJSRuntime)(unsafe.Pointer(rt)).Fmalloc_state.Fmalloc_size+size > (*TJSRuntime)(unsafe.Pointer(rt)).Fmalloc_gc_threshold)
	if force_gc != 0 {
		x_JS_RunGC(tls, rt)
		(*TJSRuntime)(unsafe.Pointer(rt)).Fmalloc_gc_threshold = (*TJSRuntime)(unsafe.Pointer(rt)).Fmalloc_state.Fmalloc_size + (*TJSRuntime)(unsafe.Pointer(rt)).Fmalloc_state.Fmalloc_size>>libc.Int32FromInt32(1)
	}
}

func _js_malloc_usable_size_unknown(tls *libc.TLS, ptr uintptr) (r Tsize_t) {
	return uint64(0)
}

func x_js_malloc_rt(tls *libc.TLS, rt uintptr, size Tsize_t) (r uintptr) {
	return (*(*func(*libc.TLS, uintptr, Tsize_t) uintptr)(unsafe.Pointer(&struct{ uintptr }{(*TJSRuntime)(unsafe.Pointer(rt)).Fmf.Fjs_malloc})))(tls, rt+32, size)
}

func x_js_free_rt(tls *libc.TLS, rt uintptr, ptr uintptr) {
	(*(*func(*libc.TLS, uintptr, uintptr))(unsafe.Pointer(&struct{ uintptr }{(*TJSRuntime)(unsafe.Pointer(rt)).Fmf.Fjs_free})))(tls, rt+32, ptr)
}

func x_js_realloc_rt(tls *libc.TLS, rt uintptr, ptr uintptr, size Tsize_t) (r uintptr) {
	return (*(*func(*libc.TLS, uintptr, uintptr, Tsize_t) uintptr)(unsafe.Pointer(&struct{ uintptr }{(*TJSRuntime)(unsafe.Pointer(rt)).Fmf.Fjs_realloc})))(tls, rt+32, ptr, size)
}

func x_js_malloc_usable_size_rt(tls *libc.TLS, rt uintptr, ptr uintptr) (r Tsize_t) {
	return (*(*func(*libc.TLS, uintptr) Tsize_t)(unsafe.Pointer(&struct{ uintptr }{(*TJSRuntime)(unsafe.Pointer(rt)).Fmf.Fjs_malloc_usable_size})))(tls, ptr)
}

func x_js_mallocz_rt(tls *libc.TLS, rt uintptr, size Tsize_t) (r uintptr) {
	var ptr uintptr
	_ = ptr
	ptr = x_js_malloc_rt(tls, rt, size)
	if !(ptr != 0) {
		return libc.UintptrFromInt32(0)
	}
	return libc.Xmemset(tls, ptr, 0, size)
}

// C documentation
//
//	/* Throw out of memory in case of error */
func x_js_malloc(tls *libc.TLS, ctx uintptr, size Tsize_t) (r uintptr) {
	var ptr uintptr
	_ = ptr
	ptr = x_js_malloc_rt(tls, (*TJSContext)(unsafe.Pointer(ctx)).Frt, size)
	if libc.BoolInt64(!!!(ptr != 0)) != 0 {
		x_JS_ThrowOutOfMemory(tls, ctx)
		return libc.UintptrFromInt32(0)
	}
	return ptr
}

// C documentation
//
//	/* Throw out of memory in case of error */
func x_js_mallocz(tls *libc.TLS, ctx uintptr, size Tsize_t) (r uintptr) {
	var ptr uintptr
	_ = ptr
	ptr = x_js_mallocz_rt(tls, (*TJSContext)(unsafe.Pointer(ctx)).Frt, size)
	if libc.BoolInt64(!!!(ptr != 0)) != 0 {
		x_JS_ThrowOutOfMemory(tls, ctx)
		return libc.UintptrFromInt32(0)
	}
	return ptr
}

func x_js_free(tls *libc.TLS, ctx uintptr, ptr uintptr) {
	x_js_free_rt(tls, (*TJSContext)(unsafe.Pointer(ctx)).Frt, ptr)
}

// C documentation
//
//	/* Throw out of memory in case of error */
func x_js_realloc(tls *libc.TLS, ctx uintptr, ptr uintptr, size Tsize_t) (r uintptr) {
	var ret uintptr
	_ = ret
	ret = x_js_realloc_rt(tls, (*TJSContext)(unsafe.Pointer(ctx)).Frt, ptr, size)
	if libc.BoolInt64(!!(!(ret != 0) && size != uint64(0))) != 0 {
		x_JS_ThrowOutOfMemory(tls, ctx)
		return libc.UintptrFromInt32(0)
	}
	return ret
}

